  const group = st.groups.find((g) => g.cards.includes(c));
  if (!group || group.heading === null) return null;
  const section = sectionOf(choices, st.cards[group.heading].blocks[0]);
  const { key, value } = block.rows[row];
  const given = section && Object.prototype.hasOwnProperty.call(section, key) ? section[key] : null;
  const list = Array.isArray(given) ? given : Array.isArray(given?.values) ? given.values : null;
  if (!list || !list.length) return null;
  const values = list.map(valueOf);
  const exact = values.findIndex((v) => v.value === value);
  const any = values.findIndex((v) => v.value.toLowerCase() === value.toLowerCase());
  const lit = exact !== -1 ? exact : any !== -1 ? any : null;
  const words = values.map((v) => v.value);
  const rocker = values.length === 2 && words.includes('on') && words.includes('off') && lit !== null;
  const closed = !Array.isArray(given) && given.given === true;
  return { values, lit, rocker, ...(closed ? { closed } : {}) };
