/**
 * Editing a card (SPEC.md, "Editing cards"). A UI says what was done --
 * these rows in this order, these items, these words -- and these
 * functions write the markdown, so every platform writes the same.
 * A card is named by its index in `stack(markdown).cards`.
 *
 * Whatever is unchanged keeps its lines as written: a row or item the
 * UI did not touch is copied, not rewritten. And an edit that would
 * change how any other card reads is refused, never made: a list
 * written so that the next paragraph joins its last item, a fence that
 * would swallow what follows. The edited card itself may become
 * anything its new text reads as.
 */

const { stack, firstParagraph } = require('./stack');
const { read, readRow, isBlank, ROW } = require('./blocks');

const MARKER = /^(\s*)([-*+]|\d{1,9}[.)])([ \t]+|$)/;

function cardOf(st, c, markdown) {
  if (!st.cards[c]) throw new RangeError(`there is no card ${c}`);
  return markdown === undefined ? st.cards[c] : own(st.cards[c], markdown);
}

